<?php namespace Workspace; ?>
<div class="projectmeta"><span class="pill"><?= h(DOC_KINDS[$doc['kind']]) ?></span><a href="<?= h(url('project',['id'=>$doc['project_id']])) ?>"><?= h($doc['project_title']) ?></a></div>
<details class="editor"><summary>Добавить версию</summary><form method="post" enctype="multipart/form-data" class="formgrid"><?php formFields('document.version') ?><input type="hidden" name="project_id" value="<?= (int)$doc['project_id'] ?>"><input type="hidden" name="document_id" value="<?= (int)$doc['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$versions[0]['revision'] ?>">
<label>Новый PDF до 2 МиБ<input name="pdf" type="file" accept=".pdf,application/pdf" required></label><div class="formend"><button class="primary">Сохранить версию</button></div></form></details>
<section class="panel"><div class="panelhead"><h2>История версий</h2></div><?php foreach ($versions as $v): ?><div class="versionrow"><div><strong>Версия <?= (int)$v['revision'] ?></strong><small><?= h($v['created_at']) ?> UTC · <?= h($v['name']) ?> · <?= (int)$v['size'] ?> байт</small><details class="minor"><summary>SHA-256</summary><code><?= h($v['sha256']) ?></code></details></div><a class="button secondary" href="<?= h(url('download',['id'=>$doc['id'],'v'=>$v['revision']])) ?>">Скачать PDF</a></div><?php endforeach ?></section>
